#include <stdio.h>

#define CAN_FISH (1 << 0)
#define CAN_NAP  (1 << 2)

int main(void) {
    int cat = {start};

    printf("能领小鱼干吗？%s\n", (cat & CAN_FISH) ? "能" : "不能");
    printf("能睡猫窝吗？%s\n", (cat & CAN_NAP) ? "能" : "不能");

    cat = cat & ~CAN_NAP;

    printf("收回睡猫窝之后：%s\n", (cat & CAN_NAP) ? "能" : "不能");
    printf("还能领小鱼干吗？%s\n", (cat & CAN_FISH) ? "能" : "不能");
    return 0;
}
